    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1h44y157gq', 'course-bili-bv1h44y157gq', '100001', '0', 'BILI-PRO-EQ7TZE', 'course-category-programming', 'instructor-bili-146668655', '千锋教育前端TypeScript入门视频教程（顶配版TS入门教程）', '109 讲完整课程 · 11 小时 29 分钟', '本套视频带你从官网的知识点入手，结合案例循序渐进带你入门TypeScript。课程共设计四个篇章，案例篇及项目篇。在看视频的同时，还整理了详细的视频的文字版，你可以看完视频，对着笔记来练习。本套视频将帮大', '课程简介：本套视频带你从官网的知识点入手，结合案例循序渐进带你入门TypeScript。课程共设计四个篇章，案例篇及项目篇。在看视频的同时，还整理了详细的视频的文字版，你可以看完视频，对着笔记来练习。本套视频将帮大家从 0 到 1 学习TypeScript,让你能读懂别人的TS代码的同时也能编写自己的TS代码。课程结构：共 14 章 109 讲，累计时长 11 小时 29 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/1c46fa0cc9a368f2bd98c15f531fe063f4abce2e.jpg', '["编程开发","零基础","实战项目","顶配版TS入门教程"]', 41345, 109, 117438, '4.6', 13374, 'BV1H44y157gq', NULL, NULL, NULL, 1, 0, 'standard', NULL, '千锋教育', 0, 'tenant', 'published', '2022-01-12T04:55:03.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
