    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1u24y1y7jf', 'course-bili-bv1u24y1y7jf', '100001', '0', 'BILI-PRO-Z9HLG8', 'course-category-programming', 'instructor-bili-76542346', 'Redis视频从入门到高级，redis视频教程详解，Redis一课在手，别无所求', '178 讲完整课程 · 41 小时 20 分钟', '视频配套：电子文档+源码+工具资料等【评论区置顶】获取；学完本教程学maven进阶：BV1kg4y187td 本套教程基于对企业级应用的深度调研产出，采用Redis最新版本7.0进行讲授，兼容5.0和6.0版本，', '课程简介：视频配套：电子文档+源码+工具资料等【评论区置顶】获取；学完本教程学maven进阶：BV1kg4y187td 本套教程基于对企业级应用的深度调研产出，采用Redis最新版本7.0进行讲授，兼容5.0和6.0版本，全线覆盖企业一线开发版本。课程涵盖Redis全套知识体系，从Redis用法到底层工作原理，对零基础友好，对提升者给力。学习本套教程，无需再查找任何其它Redis相关资料，重难点全程动画图解。教程一大亮点是对于分布式锁的系统讲授，除了最常见的8种锁实现外，还深度剖析了Redission分布式锁的8种锁机制。课程结构：共 23 章 178 讲，累计时长 41 小时 20 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/0c56f36d6206b486e658935f66be266770e2391f.jpg', '["编程开发","零基础","实战项目","redis视频教程详解","Redis一课在手","别无所求"]', 148850, 178, 282027, '4.3', 13213, 'BV1U24y1y7jF', NULL, NULL, NULL, 1, 0, 'standard', NULL, '动力节点', 0, 'tenant', 'published', '2022-11-22T07:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
