    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6264323', 'course-bili-season-6264323', '100001', '0', 'BILI-PRO-ML0547', 'course-category-programming', 'instructor-bili-12890453', '编程知识百科', '26 讲完整课程 · 4 小时 44 分钟', '1 个视频带你从 0 实战入门 MySQL 数据库，小白可懂的学习路线，程序员保姆级教程。看完这个视频，你就知道数据库到底是啥了！编程学习教程+实战项目+简历模板：codefather.cn 视频详细讲解 MySQL', '课程简介：1 个视频带你从 0 实战入门 MySQL 数据库，小白可懂的学习路线，程序员保姆级教程。看完这个视频，你就知道数据库到底是啥了！编程学习教程+实战项目+简历模板：codefather.cn 视频详细讲解 MySQL 数据库的核心概念、SQL 语言基础、索引优化、事务处理、慢查询排查、数据备份恢复、主从复制、读写分离、分库分表、高可用集群架构等知识。无论你是刚入门的后端开发新手，还是想要系统学习关系型数据库的程序员，这期内容都能帮你快速掌握 MySQL 必备知识点。视频还涉及 JDBC、MyBatis、Spring 事务管理等 Java 开发常用技术栈，同样适合准备面试刷题、想要深入理解数据库底层原理、或者正在做项目需要用到 MySQL 的同学观看。记得三连支持、关注鱼皮，让更多朋友学到知识哦~ 课程结构：共 1 章 26 讲，累计时长 4 小时 44 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/fb7f51b19fbfd959edee9ffc81d6c3b4bc3d6486.jpg', '["编程开发","零基础","实战项目","编程知识百科"]', 17075, 26, 129645, '4.9', 49515, 'BV1iJSLBbEyD', NULL, NULL, NULL, 1, 0, 'standard', NULL, '程序员鱼皮', 0, 'tenant', 'published', '2025-11-28T04:06:56.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
