INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ht411f7r7', 'course-bili-bv1ht411f7r7', '100001', '0', 'BILI-PRO-A24GJL', 'course-category-programming', 'instructor-bili-484326544', '生信小白的Linux保姆级教程', '37 讲完整课程 · 9 小时 57 分钟', '由于单细胞测序等生物信息学分析的数据一般非常巨大，各位自己的电脑很难去处理这类大数据，所以大家也无法避免的需要使用服务器，但涉及到服务器的使用，就无法绕开Linux的学习很多没有linux知识的小伙伴在遇到R包安装问题、', '课程简介：由于单细胞测序等生物信息学分析的数据一般非常巨大，各位自己的电脑很难去处理这类大数据，所以大家也无法避免的需要使用服务器，但涉及到服务器的使用，就无法绕开Linux的学习很多没有linux知识的小伙伴在遇到R包安装问题、或者是在shell命令行中使用软件时遇到问题都会来找我寻求帮助。既然大家有需求，与其我一个个的给大家发鱼，不如就开一个系列，和大家一起系统性地入门一下linux，我也借此复习一遍我那贫瘠的linux知识。课程结构：共 5 章 37 讲，累计时长 9 小时 57 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/97260427747de01b01038196786c72746149e49e.png', '["编程开发","零基础","实战项目"]', 35826, 37, 31991, '4.5', 7873, 'BV1hT411F7r7', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'Biomamba-生信基地', 0, 'tenant', 'published', '2022-08-25T14:09:40.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
