    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6995788', 'course-bili-season-6995788', '100001', '0', 'BILI-PRO-BFDDHF', 'course-category-programming', 'instructor-bili-607942962', '基于.Net Core微服务架构视频教程', '46 讲完整课程 · 645 小时 30 分钟', '基于.Net Core微服务架构视频教程。共 46 讲，累计 645.5 小时，由 超级工程师阿喵 讲解，章节结构完整，可直接在课程播放器中观看。', '吃透分布式核心！还在为微服务架构设计头疼？还在纠结.Net Core 分布式项目怎么落地？这套保姆级教程带你从零搭建企业级微服务系统，拒绝纸上谈兵，全程实战驱动！✅ 核心内容速览 微服务基础扫盲：架构选型、服务拆分原则、与单体架构的优劣对比 .Net Core 核心技术栈：依赖注入 / 中间件 / 配置中心实战，夯实底层基础 分布式核心组件：服务注册与发现（Consul/Eureka）、负载均衡、熔断降级（Polly） 数据一致性方案：分布式事务（Saga/TCC）、分库分表实操 网关与安全：Ocelot 网关配置、JWT 鉴权、接口限流实战 项目实战落地：从零搭建电商微服务 Demo，涵盖订单 / 支付 / 用户三大核心模块 部署与监控：Docker 容器化部署、ELK 日志收集、Prometheus 监控告警 💡 适合人群 .Net Core 开发者想进阶微服务架构 后端工程师需要搭建分布式项目 高校学生 / 转行人员想掌握企业级实战技能 🎁 配套资源全套源码 + 课件文档 + 组件配置手册，课程结构：共 1 章 46 讲，累计时长 645 小时 30 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'advanced', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/6f943420d0eefabb00c85dd87b61a17b6041fa9f.jpg', '["编程开发","零基础","实战项目","基于.Net"]', 2323849, 46, 114, '4.3', 17, 'BV1xsvqBeEuk', NULL, NULL, NULL, 1, 0, 'standard', NULL, '超级工程师阿喵', 0, 'tenant', 'published', '2025-12-28T00:27:31.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
