INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1bk4y1279u', 'course-bili-bv1bk4y1279u', '100001', '0', 'BILI-PRO-C75X44', 'course-category-programming', 'instructor-bili-402612604', 'Rust 基础视频教程 44 讲', '44 讲完整课程 · 7 小时 10 分钟', '专注于安全，尤其是并发安全，支持函数式和命令式以及泛型等编程范式的多范式语言。Rust在语法上和C++类似，但是设计者想要在保证性能的同时提供更好的内存安全。', '专注于安全，尤其是并发安全，支持函数式和命令式以及泛型等编程范式的多范式语言。Rust在语法上和C++类似，但是设计者想要在保证性能的同时提供更好的内存安全。Rust最初是由Mozilla研究院的Graydon Hoare设计创造，然后在Dave Herman,Brendan Eich以及很多其他人的贡献下逐步完善的。Rust的设计者们通过在研发Servo网站浏览器布局引擎过程中积累的经验优化了Rust语言和Rust编译器。课程结构：共 6 章 44 讲，累计时长 7 小时 10 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/fd70f2178d142d87208c946e3b7f730e6ccd51bb.png', '["编程开发","零基础","实战项目","Rust","基础视频教程"]', 25809, 44, 1821, '4.3', 248, 'BV1bk4y1279U', NULL, NULL, NULL, 1, 0, 'standard', NULL, '业余草', 0, 'tenant', 'published', '2020-09-05T03:35:21.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
