    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv18crfbpesi', 'course-bili-bv18crfbpesi', '100001', '0', 'BILI-PRO-WUP9AS', 'course-category-programming', 'instructor-bili-9028718', 'Android开发实战演练—用Kotlin开发天气预报APP2.0', '8 讲完整课程 · 56 分钟', '用Kotlin开发一个天气预报2.0的AndroidApp。', '课程简介：用Kotlin开发一个天气预报2.0的AndroidApp。登录、注册、退出登录、 记住登录状态，下次启动直接登录进入主页 - 支持当前天气、未来3天天气；天气、气温、风向、风力、湿度、更新时间 未来3天天气：天气、最低气温、最高气温、风向、风力、湿度、白天夜晚天气 - 支持城市收藏管理；添加、删除城市 点击城市进入该城市的天气详情 - 支持城市搜索 - 支持背景切换 过ViewPager展示可切换的背景 背景信息存储到数据库，下次启动自动应用背景 - 采用侧滑菜单页面结构，侧滑菜单结构，支持侧滑菜单、主界面、城市收藏、关于页面 涉及技术： - 布局 RelativeLayout、LinearLayout、TextView、ImageView、Button、EditText等的使用 - 复杂UI控件的使用：列表RecyclerView、Spinner控件、ViewPager、DrawerLayout、NavigationView、Toolbar、FragmentContainerView、MaterialCardView等。- 网络请求，使用HttpURLConnection原生方式请求网络，结合数据流处 课程结构：共 1 章 8 讲，累计时长 56 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/840b9bdffc00fa75ba3b389bccb3bb195f298518.jpg', '["编程开发","零基础","实战项目"]', 3380, 8, 1789, '4.4', 316, 'BV18CrfBpESi', NULL, NULL, NULL, 1, 0, 'standard', NULL, '子林Android', 0, 'tenant', 'published', '2026-01-15T10:20:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
