INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1a8mdzueu5', 'course-bili-bv1a8mdzueu5', '100001', '0', 'BILI-PRO-UV3US5', 'course-category-programming', 'instructor-bili-291133733', 'React+TS+Nest秒级RBAC权限方案！一套轻松掌握Websocket开发', '1 讲完整课程 · 1 小时 9 分钟', 'React + TS + Nest 全栈WebSocket实战：RBAC权限实时更新系统 核心内容： - 前端WebSocket全流程 - 如何用Socket.IO建立连接 - 监听服务端事件，动态更新权限/UI - 处', '课程简介：React + TS + Nest 全栈WebSocket实战：RBAC权限实时更新系统 核心内容： - 前端WebSocket全流程 - 如何用Socket.IO建立连接 - 监听服务端事件，动态更新权限/UI - 处理断线重连、心跳检测等生产环境问题 后端WebSocket开发 - 使用Nest.js搭建WebSocket服务 - 管理用户连接，实现精准消息推送（只通知目标用户） - 结合RBAC模型，处理权限变更逻辑 前后端通信实战： - 定义通信协议（事件名、数据格式） - 从后端推送到前端响应的完整链路 - 性能优化和常见问题解决方案 掌握： - 前端WebSocket完整使用方案 - 后端WebSocket服务的开发和优化 - 生产级实时通信系统的实现思路 技术栈： - 前端：React (TypeScript) + Socket.IO Client - 后端：Nest.js + WebSocket (Socket.IO) #React #NestJS #WebSocket #全栈开发 #权限控制 课程结构：共 1 章 1 讲，累计时长 1 小时 9 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'intermediate', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/96c551faef4a62de58d9df37b0303acc8b5ac86e.jpg', '["编程开发","零基础","实战项目","实战教程","React","TS"]', 4148, 1, 321, '4.5', 138, 'BV1a8MdzUEU5', NULL, NULL, NULL, 1, 0, 'standard', NULL, '镰小策ovo', 0, 'tenant', 'published', '2025-07-12T16:10:02.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
