    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1wiat6neqr', 'course-bili-bv1wiat6neqr', '100001', '0', 'BILI-PRO-B4K1JV', 'course-category-programming', 'instructor-bili-350243622', '零基础学 Linux：从虚拟机搭建到部署服务器，一套教程全搞定，运维工程师入门第一课，学完可工作', '37 讲完整课程 · 13 小时 0 分钟', '本套视频教程旨在深入讲解Linux系统的基本知识与实操技能，涵盖了从系统介绍、虚拟机部署到故障排查、权限管理、磁盘管理及进程管理等多个方面。课程详细讲解了如何使用Linux命令行、管理用户权限、优化系统、分析日志以及处理', '课程简介：本套视频教程旨在深入讲解Linux系统的基本知识与实操技能，涵盖了从系统介绍、虚拟机部署到故障排查、权限管理、磁盘管理及进程管理等多个方面。课程详细讲解了如何使用Linux命令行、管理用户权限、优化系统、分析日志以及处理系统常见问题。课程还介绍了如何使用常见工具如Vim、思维导图工具、流程图工具等，以帮助学员更高效地解决实际运维中的问题。无论是初学者还是进阶用户，课程均为Linux学习提供了全方位的指导。课程结构：共 5 章 37 讲，累计时长 13 小时 0 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/71f9308aa5c9fcf7db6afc202b13351086fa4e2a.jpg', '["编程开发","零基础","实战项目","运维宝藏","零基础学","Linux"]', 46858, 37, 181, '4.3', 15, 'BV1wiat6NEQr', NULL, NULL, NULL, 1, 0, 'standard', NULL, '老男孩IT教育', 0, 'tenant', 'published', '2026-09-29T10:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
